        id => 'node_5',
        op => 'Add',
        inputs => ['node_3', 'node_4'],
        attributes => {
            left => { op => 'NodeRef', node_id => 'node_3' },
            right => { op => 'NodeRef', node_id => 'node_4' }
        }
    );
    $graph->add_node($add3);

